                (
                    parameter,
                    self._updated(
                        parameter.data,
                        parameter.grad,
                        self.m[index],
                        self.v[index],
                        bias1,
                        bias2,
                    ),
                )
            )
        for parameter, (new_data, new_m, new_v) in updates:
            parameter.data = new_data
            index = self.parameters.index(parameter)
            self.m[index] = new_m
            self.v[index] = new_v
